public async Task<InstructorClientProfileDto?> GetAttendeeProfileAsync(string clientId)
{
    var c = await _clients.Find(x => x.Id == clientId).FirstOrDefaultAsync();
    if (c == null) return null;

    // Visit history: count of checked-in attendances and the most recent one.
    // (Status is stored as "CHECKED_IN"; the roster UI relabels it "ARRIVED".)
    var visited = await _attendances
        .Find(a => a.ClientId == clientId && (a.Status == "CHECKED_IN" || a.Status == "ARRIVED"))
        .ToListAsync();

    DateTime? lastVisit = null;
    if (visited.Count > 0)
    {
        var sessionIds = visited.Where(a => a.CalendarSessionId != null)
            .Select(a => a.CalendarSessionId!).Distinct().ToList();
        var sessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.In(s => s.Id, sessionIds))
            .ToListAsync();
        var now = DateTime.UtcNow;
        lastVisit = sessions.Where(s => s.StartTime <= now)
            .Select(s => (DateTime?)s.StartTime)
            .DefaultIfEmpty(null)
            .Max();
    }

    return new InstructorClientProfileDto
    {
        ClientId = c.Id!,
        Name = c.FullName,
        Email = c.Email,
        Phone = c.FullPhoneNumber,
        MedicalHistory = c.MedicalHistory,
        DateOfBirth = c.DateOfBirth,
        ReferralSource = c.ReferralSource,
        Tags = c.Tags ?? new List<string>(),
        TotalVisits = visited.Count,
        LastVisit = lastVisit,
        MemberSince = c.CreatedAt,
    };
}

