            var take = Math.Min(pkg.CreditsRemaining, remainingToDeduct);
            pkg.CreditsRemaining -= take;
            pkg.CreditsUsed += take;

            if (pkg.CreditsRemaining == 0) pkg.Status = "COMPLETED";
            else if (pkg.CreditsRemaining <= 2) pkg.Status = "LOW_BALANCE";

