/// credit branch. Deducts one credit per booked seat (<see cref="Attendance.Quantity"/>,
/// min 1) for the session's format, stamps the attendance fully paid by credit, and
/// records a 0đ PAID invoice linked back to the attendance for the audit trail.
/// CAUTION: this debits REAL prepaid credits — there is no money path here.
/// </summary>
private async Task<object> SettleBookingWithCreditAsync(
    Attendance attendance, CalendarSession? session, IInvoiceService invoiceService)
{
    // Already settled by credit — don't double-deduct the wallet.
    if (string.Equals(attendance.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase))
        throw new BusinessRuleException("BOOKING.ALREADY_CREDIT_PAID",
            "This booking has already been paid with package credit.");

    // Don't let a credit settlement erase a prior cash/card payment: the credit path
    // zeroes AmountPaid below, which would wipe a partial cash payment while its
    // invoice still stands (a debit/credit mismatch). Settle the remaining balance
    // with cash/card instead.
    if ((attendance.AmountPaid ?? 0m) > 0m)
        throw new BusinessRuleException("BOOKING.ALREADY_PARTIALLY_PAID",
            "This booking already has a payment recorded; settle the remaining balance with cash or card, not package credit.");

    // The session (and therefore its Format) is required to pick the right wallet.
    if (session == null || string.IsNullOrWhiteSpace(session.Format))
        throw new BusinessRuleException("BOOKING.NO_SESSION",
            "Cannot pay with package credit: this booking has no associated class session.");

    var format = session.Format;
    var seats = Math.Max(1, attendance.Quantity);

    // Resolve a usable package (ACTIVE + LOW_BALANCE) for this client + format.
    var packages = (await _walletService.GetActivePackagesForClientAsync(attendance.ClientId, format)).ToList();
    if (packages.Count == 0)
        throw new BusinessRuleException("BOOKING.NO_PACKAGE",
            $"No active {format} package found for this client. Choose a cash/card payment instead.");

    var resolvedPackageId = packages.First().Id;

    // Deduct one credit per seat. DeductCreditAsync is atomic at the request level:
    // it returns false (no partial deduction) when total credits < seats.
    var deducted = await _walletService.DeductCreditAsync(
        attendance.ClientId, format, "pos-collect-" + attendance.Id, seats);
    if (!deducted)
        throw new BusinessRuleException("BOOKING.CREDIT_DEDUCTION_FAILED",
            "Insufficient credits for this booking. Please check the client's wallet or collect cash/card instead.");

    // Stamp the attendance as fully paid by credit (mirror walk-in credit booking).
    var attUpdate = Builders<Attendance>.Update
        .Set(a => a.PaymentMethod, "PACKAGE_CREDIT")
        .Set(a => a.PackageInstanceId, resolvedPackageId)
        .Set(a => a.AmountPaid, 0m)
        .Set(a => a.AmountDueAtStudio, 0m);
    await _attendances.UpdateOneAsync(a => a.Id == attendance.Id, attUpdate);

    // 0đ PAID invoice for the audit trail (no money changes hands — revenue was
    // captured when the package was purchased). Link the line to the attendance.
    var creditInvoice = new Invoice
    {
        ClientId = attendance.ClientId,
        TotalDiscount = 0m,
        TotalTax = 0m,
        IssueDate = DateTime.UtcNow,
        Notes = $"Studio collection (package credit): {session.ClassName} on {StudioTime.Local(session.StartTime):yyyy-MM-dd HH:mm}",
        PaymentMethod = "CREDIT",
        Lines = new List<InvoiceLine>
        {
            new InvoiceLine
            {
                ProductId = session.ClassBlueprintId ?? string.Empty,
                Description = ClassFormatLabel(session.Format),
                Quantity = seats,
                UnitPrice = 0m,
                LineDiscount = 0m,
                AttendanceId = attendance.Id,
                CalendarSessionId = attendance.CalendarSessionId,
                ProductTypeSnapshot = "CLASS",
            }
        }
    };

    var createdInvoice = await invoiceService.CreateInvoiceAsync(creditInvoice);

    // TotalNet = 0 → flip to PAID directly. No Payment row needed.
    await _invoices.UpdateOneAsync(
        i => i.Id == createdInvoice.Id,
        Builders<Invoice>.Update.Set(i => i.Status, "PAID"));

    return new
    {
        invoiceId = createdInvoice.Id,
        invoiceNumber = createdInvoice.InvoiceNumber,
        amountCollected = 0m,
        totalPaid = 0m,
        remainingDue = 0m,
        paymentMethod = "PACKAGE_CREDIT",
        usedCredit = true,
        packageInstanceId = resolvedPackageId,
        creditsDeducted = seats,
    };
}

